 const inAttesa: Parameters<AvvioNavigazione>[] = [];
 const MAX_IN_ATTESA = 20;

+/**
+ * 20/11/2026 (R03-004) — LA FINESTRA PRIMA DELL'SDK, CHIUSA ORA CHE IL DSN SI ACCENDE.
+ *
+ * Due ascoltatori nativi, messi subito e in modo sincrono, tengono da parte gli errori che
+ * scoppiano mentre il pezzo con l'SDK sta arrivando, e li consegnano a Sentry appena c'è. Poi si
+ * tolgono: da lì in avanti ascolta Sentry. Il tetto è basso come quello delle navigazioni.
+ */
+const erroriInAttesa: unknown[] = [];
+const MAX_ERRORI_IN_ATTESA = 10;
+function tieniDaParte(evento: Event): void {
+  if (erroriInAttesa.length >= MAX_ERRORI_IN_ATTESA) return;
+  erroriInAttesa.push(
+    'reason' in evento ? (evento as PromiseRejectionEvent).reason : ((evento as ErrorEvent).error ?? (evento as ErrorEvent).message),
+  );
+}
+
 if (SENTRY_DSN) {
+  if (typeof window !== 'undefined') {
+    window.addEventListener('error', tieniDaParte);
+    window.addEventListener('unhandledrejection', tieniDaParte);
+  }
   void import('@sentry/nextjs').then((S) => {
     S.init(opzioniSentry() as Parameters<typeof S.init>[0]);
+    if (typeof window !== 'undefined') {
+      window.removeEventListener('error', tieniDaParte);
+      window.removeEventListener('unhandledrejection', tieniDaParte);
+    }
+    for (const errore of erroriInAttesa.splice(0)) S.captureException(errore);
     avvioNavigazione = S.captureRouterTransitionStart;
     for (const argomenti of inAttesa.splice(0)) avvioNavigazione(...argomenti);
   });

